const o=[{id:"manifiesto-de-la-ceniza",titulo:"Manifiesto de la Ceniza: La Destrucción de la Forma como Renacimiento del Ser",subtitulo:"La ceniza no es el residuo de una derrota, sino el máximo de la pureza",autor:"Elio Jerez Contreras",biografiaAutor:"Ensayista e investigadora en estudios de género y representaciones del cuerpo disidente.",categoria:"Ensayos",resumen:"La identidad femenina ha sido, históricamente, una arquitectura erigida sobre la mirada ajena. Desde la indumentaria hasta las formas de sentir, este ensayo explora la ceniza como acto refundacional de la autonomía estética y política.",contenido:"<p class='drop-cap'>La identidad femenina ha sido, históricamente, una arquitectura erigida sobre la mirada ajena. Desde la indumentaria hasta las formas de amar o callar, el cuerpo se ha moldeado para encajar en moldes preconcebidos.</p><p>Hablar de la ceniza no es invocar la ruina o el abatimiento. Por el contrario, reclamamos el fuego como el único elemento capaz de purgar las expectativas impuestas. Cuando la forma estándar colapsa, lo que queda no es la nada: es la materia primordial libre de mandatos.</p><blockquote class='font-serif italic text-berry-700 my-4 pl-4 border-l-2 border-berry-700'>«La ceniza no es el residuo de una derrota, sino el máximo de la pureza.»</blockquote><p>Desde las escrituras anfibias, proponemos desarmar los andamios del recato y habitarnos desde la imperfección luminosa del residuo.</p>",fecha:"22 de Agosto, 2024",pdfUrl:"#",destacado:!0,lecturaMinutos:7},{id:"manual-del-usuario-carne-estandar",titulo:"MANUAL DEL USUARIO: PROTOCOLO DE AJUSTE PARA LA CARNE ESTÁNDAR",subtitulo:"Entonces, que falle. Que se rompa la simetría. Que la hegemonía se quede sin usuaria.",autor:"Ingrid Escobar Ulloa",biografiaAutor:"Escritora y narradora chilena. Explora escrituras experimentales e híbridas.",categoria:"Escrituras anfibias",resumen:"Un texto híbrido e irónico estructurado como manual técnico que desmonta las exigencias del cuerpo hegemónico y celebra la falla sistémica.",contenido:"<p class='drop-cap'><strong>Paso 1: Identificación de la falla somática.</strong> Al despertar, examine las extremidades en busca de disidencias o asimetrías no autorizadas por los catálogos del deseo oficial.</p><blockquote class='font-serif italic text-berry-700 my-4 pl-4 border-l-2 border-berry-700'>«Entonces, que falle. Que se rompa la simetría. Que la hegemonía se quede sin usuaria.»</blockquote><p>El dispositivo social exige que el recipiente no emita ruidos fuera de tono. Sin embargo, en los rincones del vestuario y de la calle, los cuerpos aprenden a descoser las costuras del traje humano por defecto.</p>",fecha:"24 de Agosto, 2024",pdfUrl:"#",destacado:!0,lecturaMinutos:6},{id:"el-cuerpo-que-no-cabe",titulo:"El cuerpo que no cabe: pedagogías queer desde la incomodidad",subtitulo:"Quizá el problema nunca fue el cuerpo. Quizá el problema fue la medida.",autor:"Pau Cerón Calvente",biografiaAutor:"Investigador en pedagogías feministas, estudios queer y corporalidades disidentes.",categoria:"Ensayos",resumen:"Una investigación sobre cómo las instituciones y arquitecturas normativas intentan acotar los cuerpos disidentes y la urgencia de reivindicar la incomodidad como aprendizaje político.",contenido:"<p class='drop-cap'>Habitar un espacio que no ha sido pensado para una es un ejercicio cotidiano de contorsión. Las sillas del aula, las casillas de los formularios y los pronombres automáticos operan como artefactos de contención.</p><blockquote class='font-serif italic text-berry-700 my-4 pl-4 border-l-2 border-berry-700'>«Quizá el problema nunca fue el cuerpo. Quizá el problema fue la medida.»</blockquote><p>La pedagogía queer de la incomodidad no busca pacificar la diferencia para volverla asimilable. Reivindica el desborde y la interrupción como el instante exacto donde la estructura cruje y deja ver la luz.</p>",fecha:"21 de Agosto, 2024",pdfUrl:"#",destacado:!1,lecturaMinutos:8},{id:"mas-alla-del-dique",titulo:"Más allá del dique",subtitulo:"No van nunca al baño, no duermen, no comen, no rezan, no ríen, no se distraen, no se tiran.",autor:"Iria Fariñas",biografiaAutor:"Poeta y creadora. Autora de diversas publicaciones sobre poesía y corporalidad.",categoria:"Escrituras anfibias",resumen:"Poética expandida e híbrida sobre los diques de contención social, el agua amarga y la corriente de los cuerpos en resistencia.",contenido:"<blockquote class='font-serif italic text-lg leading-relaxed text-berry-800 my-4 border-l-2 border-berry-700 pl-4'><p>No van nunca al baño,<br/>no duermen,<br/>no comen, no rezan,<br/>no ríen, no se distraen,<br/>no se tiran.</p></blockquote><p>El barro no pregunta por la cuna del viajero. Acepta la huella y cuando el agua baja, guarda la forma del pie como una confesión antigua de resistencia anfibia.</p>",fecha:"17 de Agosto, 2024",pdfUrl:"#",destacado:!1,lecturaMinutos:4}],r="anfibias_articulos_custom";function l(){if(typeof window>"u")return o;try{const e=localStorage.getItem(r);if(!e)return o;const a=JSON.parse(e);if(Array.isArray(a)&&a.length>0)return[...a,...o]}catch(e){console.error("Error leyendo artículos de localStorage:",e)}return o}function c(e){if(typeof window>"u")return!1;try{const a=localStorage.getItem(r);let i=[];a&&(i=JSON.parse(a));const s=e.id||e.titulo.toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/(^-|-$)+/g,""),t=[{...e,id:s,fecha:e.fecha||new Date().toLocaleDateString("es-ES",{day:"numeric",month:"long",year:"numeric"}),destacado:e.destacado||!1,lecturaMinutos:e.lecturaMinutos||5},...i];return localStorage.setItem(r,JSON.stringify(t)),!0}catch(a){return console.error("Error guardando artículo:",a),!1}}function d(){typeof window>"u"||localStorage.removeItem(r)}export{l as g,d as r,c as s};
